// OQIM network laboratory. Fluid vehicles, 1 s steps, finite receiving storage.
export const MODES=['fixed','reactive','predictive'];
export function network(n=4){return Array.from({length:n},(_,i)=>({id:`J${i+1}`,next:i<n-1?`J${i+2}`:null,capacity:35,travel:12,turn:0.15,saturation:0.7,offset:(i*12)%60}));}
export function validate(nodes){if(!Array.isArray(nodes)||nodes.length<1||nodes.length>24)throw Error('Нужно от 1 до 24 узлов');const ids=new Set(nodes.map(n=>n.id));if(ids.size!==nodes.length)throw Error('ID узлов должны быть уникальными');for(const n of nodes){if(n.coordinates!==undefined&&(!Array.isArray(n.coordinates)||n.coordinates.length!==2||!n.coordinates.every(Number.isFinite)||Math.abs(n.coordinates[0])>180||Math.abs(n.coordinates[1])>90))throw Error('Некорректные координаты');if(typeof n.id!=='string'||!n.id||n.id.length>40)throw Error('Некорректный ID');if(n.next!==null&&!ids.has(n.next))throw Error('Неизвестный следующий узел');for(const [k,min,max] of [['capacity',5,300],['travel',1,120],['turn',0,1],['saturation',0.1,3],['offset',0,59]])if(!Number.isFinite(n[k])||n[k]<min||n[k]>max)throw Error(`Недопустимое значение ${k}`);}return nodes;}
export function rng(seed){return()=>{seed|=0;seed=seed+0x6D2B79F5|0;let t=Math.imul(seed^seed>>>15,1|seed);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}
export function demand(nodes,{seconds=600,rate=650,side=180,seed=42,event=true,parking=0}={}){const random=rng(seed),poisson=lambda=>{let p=1,k=0,L=Math.exp(-lambda);do{k++;p*=random();}while(p>L);return k-1;};return Array.from({length:seconds},(_,t)=>nodes.map((_,i)=>({main:poisson((i===0?rate:rate*0.07)/3600*(event&&t>=180&&t<300?2.4:1))+(i===nodes.length-1&&t>=360&&t<420?parking/60:0),side:poisson(side/3600)})));}
export function initial(nodes){return{t:0,nodes:nodes.map(n=>({id:n.id,q:0,side:0,outside:0,transit:[],green:25,phase:'main',maxQ:0})),generated:0,completed:0,delay:0,overload:0,maxQueue:0,decisions:[],applied:[]};}
export function signal(t,node,green){const p=((t-node.offset)%60+60)%60;return p<green?'main':p<green+3?'yellow':p<green+5?'clear':p<55?'side':p<58?'yellow':'clear';}
export function step(state,nodes,input,settings={}){const index=new Map(nodes.map((n,i)=>[n.id,i]));let overloaded=false;const transfers=[];for(let i=0;i<nodes.length;i++){const s=state.nodes[i],n=nodes[i],a=input[i]||{main:0,side:0};s.outside+=a.main;s.side+=a.side;state.generated+=a.main+a.side;for(const batch of s.transit)batch.eta--;const arrived=s.transit.filter(b=>b.eta<=0);s.q+=arrived.reduce((v,b)=>v+b.count,0);s.transit=s.transit.filter(b=>b.eta>0);const room=Math.max(0,n.capacity-s.q-s.transit.reduce((v,b)=>v+b.count,0));const enter=Math.min(room,s.outside);s.q+=enter;s.outside-=enter;s.phase=signal(state.t,n,s.green);}
// Downstream space is reserved during this step, preventing concurrent overflow.
const reserved=nodes.map((n,i)=>Math.max(0,n.capacity-state.nodes[i].q-state.nodes[i].transit.reduce((v,b)=>v+b.count,0)));
for(let i=0;i<nodes.length;i++){const s=state.nodes[i],n=nodes[i];let cap=n.saturation;if(settings.block&&i===Math.floor(nodes.length/2)&&state.t>=240&&state.t<420)cap*=0.35;if(settings.parking&&i===nodes.length-1)cap*=1-Math.min(0.6,settings.parking/150);if(s.phase==='main'){const j=index.get(n.next),fraction=n.next===null?0:1-n.turn;const receiving=fraction>0?reserved[j]/fraction:Infinity;const release=Math.max(0,Math.min(s.q,cap,receiving));s.q-=release;state.completed+=release*(1-fraction);if(fraction>0){reserved[j]-=release*fraction;transfers.push({j,count:release*fraction,eta:nodes[j].travel,from:n.id});}}else if(s.phase==='side'){const release=Math.min(s.side,cap);s.side-=release;state.completed+=release;}}
for(const x of transfers)state.nodes[x.j].transit.push({count:x.count,eta:x.eta,from:x.from});for(let i=0;i<nodes.length;i++){const s=state.nodes[i];state.delay+=s.q+s.side+s.outside;s.maxQ=Math.max(s.maxQ,s.q+s.side+s.outside);state.maxQueue=Math.max(state.maxQueue,s.maxQ);if(s.q>=nodes[i].capacity*0.9||s.outside>0.01)overloaded=true;}if(overloaded)state.overload++;state.t++;return state;}
export function conserved(s){return s.completed+s.nodes.reduce((a,n)=>a+n.q+n.side+n.outside+n.transit.reduce((v,b)=>v+b.count,0),0);}
function forecastInputs(inputs,t,horizon){const start=Math.max(0,t-60),recent=inputs.slice(start,t);const avg=inputs[0].map((_,i)=>({main:recent.length?recent.reduce((a,v)=>a+v[i].main,0)/recent.length:0,side:recent.length?recent.reduce((a,v)=>a+v[i].side,0)/recent.length:0}));return Array.from({length:horizon},()=>avg);}
function objective(state,nodes,future,settings){const copy=structuredClone(state),before=copy.delay,target=copy.nodes.map(n=>n.green);if(state.activeGreens)copy.nodes.forEach((n,i)=>n.green=state.activeGreens[i]);for(const row of future){for(let i=0;i<nodes.length;i++)if(((copy.t-nodes[i].offset)%60+60)%60===0)copy.nodes[i].green=target[i];step(copy,nodes,row,settings);}return copy.delay-before+copy.nodes.reduce((a,n)=>a+15*n.outside+5*n.q,0);}
export function control(s,nodes,mode,inputs,settings){if(mode==='fixed')return;if(mode==='reactive'){s.nodes.forEach(n=>n.green=Math.max(15,Math.min(39,Math.round(50*(n.q+1)/(n.q+n.side+2)))));return;}s.activeGreens=s.nodes.map(n=>n.green);const future=forecastInputs(inputs,s.t,90);for(let i=0;i<nodes.length;i++){const old=s.nodes[i].green;let best=objective(s,nodes,future,settings),chosen=old;for(const g of [Math.max(15,old-5),Math.min(39,old+5)]){s.nodes[i].green=g;const score=objective(s,nodes,future,settings);if(score<best-1){best=score;chosen=g;}}s.nodes[i].green=chosen;if(chosen!==old)s.decisions.push({time:s.t,node:nodes[i].id,from:old,to:chosen,reason:'Минимальная прогнозная задержка по сети на горизонте 90 с; прогноз потока по последним 60 с.'});}}
export function simulate(nodes,inputs,mode,settings={}){validate(nodes);if(!MODES.includes(mode))throw Error('Unknown mode');const s=initial(nodes),frames=[];for(let t=0;t<inputs.length;t++){// Each node changes timing only at its own cycle boundary.
if(t%60===0){const proposal=structuredClone(s);control(proposal,nodes,mode,inputs,settings);s.pending=proposal.nodes.map(n=>n.green);s.decisions.push(...proposal.decisions.slice(s.decisions.length));}
for(let i=0;i<nodes.length;i++)if(((t-nodes[i].offset)%60+60)%60===0){if(s.nodes[i].green!==s.pending[i])s.applied.push({time:t,node:nodes[i].id,offset:nodes[i].offset,phaseBefore:signal(t-1,nodes[i],s.nodes[i].green),from:s.nodes[i].green,to:s.pending[i]});s.nodes[i].green=s.pending[i];}step(s,nodes,inputs[t],settings);if(t%(settings.snapshotEvery===1?1:5)===0)frames.push({t:s.t,nodes:s.nodes.map(n=>({q:n.q,side:n.side,outside:n.outside,transit:n.transit.reduce((a,b)=>a+b.count,0),phase:n.phase,green:n.green,...(settings.snapshotEvery===1?{batches:n.transit.map(b=>({...b}))}:{})})),delay:s.delay,completed:s.completed});}
return{mode,frames,finalState:s,decisions:s.decisions,metrics:{generated:s.generated,completed:s.completed,remaining:s.generated-s.completed,delay:s.delay,meanDelay:s.generated?s.delay/s.generated:0,maxQueue:s.maxQueue,overload:s.overload,conservationError:Math.abs(s.generated-conserved(s))}};}
export function compare(nodes,inputs,settings){return MODES.map(mode=>simulate(nodes,inputs,mode,settings));}

export function forecast(nodes,inputs,mode,at,horizon,settings={}){
 const past=inputs.slice(0,Math.max(1,Math.min(at,inputs.length))),base=simulate(nodes,past,mode,settings).finalState;
 const future=forecastInputs(past,base.t,horizon),state=structuredClone(base),risk=nodes.map(n=>({node:n.id,firstOverload:null,maxQueue:0,endQueue:0}));
 // Hold the latest permissible plan. This is a conditional forecast, not a learned probability.
 for(let t=0;t<horizon;t++){step(state,nodes,future[t],settings);state.nodes.forEach((n,i)=>{risk[i].maxQueue=Math.max(risk[i].maxQueue,n.q+n.side+n.outside);if(risk[i].firstOverload===null&&(n.q>=nodes[i].capacity*.9||n.outside>.01))risk[i].firstOverload=t+1;risk[i].endQueue=n.q+n.side+n.outside;});}
 return{at:base.t,horizon,method:'Constant mean arrival rate from last 60 seconds, current plans held; no calibrated confidence',risk,delay:state.delay-base.delay};
}
